    make(2, "一物體排開水的體積為 0.002 m³，取水的密度 1000 kg/m³、g＝10 N/kg。物體所受浮力大小為何？", {"A": "2 N", "B": "10 N", "C": "20 N", "D": "20000 N"}, "C", "阿基米德原理 F浮＝ρ液gV排＝1000×10×0.002＝20 N。", "辨認題目給的是排液體積，直接代入浮力公式並保留 SI 單位。", ["列出水的密度 1000 kg/m³。", "列出 g＝10 N/kg 與 V排＝0.002 m³。", "寫出 F浮＝ρgV排。", "計算 1000×10×0.002＝20。", "所以選 C。"], "medium"),
    make(3, "同一物體完全浸沒在水與食用油中，排開體積相同；水的密度大於食用油。哪個判斷正確？", {"A": "水中浮力較大", "B": "油中浮力較大", "C": "兩者浮力必相同，因為物體相同", "D": "物體完全浸沒時不受浮力"}, "A", "F浮＝ρ液gV排；兩次 V排 相同，水的密度較大，所以水中浮力較大。物體完全浸沒仍受浮力。", "固定排液體積後，只比較液體密度，不把物體重量當成浮力公式中的唯一變因。", ["確認物體兩次都完全浸沒。", "因此排開體積相同。", "比較水與食用油的密度。", "由 F浮＝ρgV，密度較大的水產生較大浮力。", "所以選 A。"], "medium"),
    make(4, "一顆鐵球沉到水底並靜止。下列敘述何者正確？", {"A": "鐵球不受浮力，因為已下沉", "B": "浮力向下且大於重力", "C": "鐵球仍受向上浮力，但浮力小於重力", "D": "鐵球的浮力一定等於重力"}, "C", "沉入水中的物體仍受液體壓力差形成的向上浮力；沉體下沉表示物重大於浮力，接觸底部時還可能有底部支持力。", "先判斷浮力是否存在，再比較浮力與重力造成的運動趨勢。", ["確認鐵球仍有一部分或全部與水接觸。", "液體壓力差仍會產生向上浮力。", "觀察它是沉體而非漂浮平衡物。", "沉體條件為 F浮 小於物重。", "所以選 C。"], "easy"),
    make(5, "木塊漂浮在水面上且保持靜止。忽略水面波動時，木塊所受浮力與木塊重量的關係為何？", {"A": "浮力大於重量", "B": "浮力等於重量", "C": "浮力小於重量", "D": "木塊漂浮所以沒有重力"}, "B", "木塊漂浮且靜止，垂直方向合力為零，因此向上浮力等於向下重量。", "把『漂浮且靜止』翻成平衡條件，而不是只看物體有沒有浸入水中。", ["列出木塊向下的重量。", "列出水對木塊向上的浮力。", "確認木塊漂浮且沒有垂直加速度。", "令向上浮力與向下重量大小相等。", "所以選 B。"], "easy"),
